"""Regenerate docs/providers.md from the provider catalog (the single source of truth).

    PYTHONPATH=src python scripts/gen_providers_md.py          # write
    PYTHONPATH=src python scripts/gen_providers_md.py --check  # exit 1 if out of date
"""
from __future__ import annotations

import sys
from pathlib import Path

from omnimonitor import catalog

OUT = Path(__file__).resolve().parents[1] / "docs" / "providers.md"

HEAD = """# Providers

<!-- Generated by scripts/gen_providers_md.py from src/omnimonitor/catalog.py. Edit the
     catalog, then regenerate; tests/test_providers_v3.py fails if this file is stale. -->

Every provider is **opt-in** (`omnimonitor providers enable <id>`, or the Providers table
in Settings). OmniMonitor only uses two kinds of source:

* **Local logs** – files the tool itself writes on this computer, opened read-only.
* **Official account APIs** – the provider's documented usage / billing endpoint, called
  with a key **you** supply in an environment variable or the chmod-600 secrets file
  (`omnimonitor secrets set NAME`). Keys are never accepted from or shown in the web UI.

OmniMonitor **never reads browser cookies, keychains or another app's login session**, and
never calls undocumented endpoints. When a number is not available it says so instead of
guessing. Costs for local logs are the cost the tool recorded, or an estimate from *your*
price table (labelled ≈).

Status: **supported** = implemented and covered by fixture tests; **partial** = implemented
with a limitation noted below; **experimental** = implemented against a format the vendor
does not document (or that we could not check on a real install), off by default, numbers
may be wrong after an update; **not supported** = no legitimate source exists today.

Confidence is honest: unless it says "tested on real files", the reader was built from the
public documentation or open-source code and tested with synthetic fixtures / mocked HTTP
only. Please report a mismatch with a redacted sample.

"""

KIND = {"billing": "Grok billing", "local_logs": "local logs", "api": "official API",
        "none": "–"}
STATUS = {"supported": "✅ supported", "partial": "🟡 partial", "experimental": "🧪 experimental",
          "not_supported": "❌ not supported"}


def _cell(s: str) -> str:
    return (s or "–").replace("|", "\\|").replace("\n", " ")


def _links(docs) -> str:
    out = []
    for d in docs:
        if d.startswith("http"):
            out.append("[%s](%s)" % (d.split("//", 1)[1].split("/", 1)[0], d))
        else:
            out.append("[%s](%s)" % (d.split("/")[-1], "../" + d if d.startswith("docs/")
                                     else d))
    return ", ".join(out) or "–"


def render() -> str:
    c = catalog.counts()
    lines = [HEAD, "## Summary\n",
             "%d entries: %d supported, %d partial, %d experimental, %d not supported.\n"
             % (len(catalog.CATALOG), c["supported"], c["partial"], c["experimental"],
                c["not_supported"]),
             "| Family | Provider | id | Status | Source | Shows | Tray % |",
             "|---|---|---|---|---|---|---|"]
    for p in catalog.CATALOG:
        lines.append("| %s | %s | `%s` | %s | %s | %s | %s |" % (
            p.family, _cell(p.name), p.id, STATUS[p.status], KIND[p.kind],
            _cell(p.shows if p.kind != "none" else p.reason.split(". ")[0].rstrip(".")),
            "yes" if p.has_limit else "–"))
    lines += ["", "## Supported, partial and experimental providers", ""]
    for p in catalog.CATALOG:
        if p.status == catalog.NOT_SUPPORTED:
            continue
        lines += ["### %s (`%s`)" % (p.name, p.id), "",
                  "| | |", "|---|---|",
                  "| Status | %s |" % STATUS[p.status],
                  "| Source | %s |" % _cell(p.source),
                  "| Auth | %s |" % _cell(p.auth),
                  "| Shows | %s |" % _cell(p.shows),
                  "| Reset period | %s |" % _cell(p.reset),
                  "| Confidence / testing | %s |" % _cell(p.confidence),
                  "| Key variables | %s |" % (", ".join("`%s`" % e for e in p.env) or "–"),
                  "| Can drive the tray %% | %s |" % ("yes" if p.has_limit else "no"),
                  "| Docs | %s |" % _links(p.docs)]
        if p.extra.get("note"):
            lines.append("| Note | %s |" % _cell(p.extra["note"]))
        lines.append("")
    lines += ["## Not supported (and what would be needed)", "",
              "| Provider | id | Why not | What would be needed | Docs |",
              "|---|---|---|---|---|"]
    for p in catalog.CATALOG:
        if p.status == catalog.NOT_SUPPORTED:
            lines.append("| %s | `%s` | %s | %s | %s |" % (_cell(p.name), p.id, _cell(p.reason),
                                                          _cell(p.needs), _links(p.docs)))
    lines += ["", "## Adding a provider", "",
              "1. Add a `ProviderInfo` entry to `src/omnimonitor/catalog.py`.",
              "2. Local logs: a scanner in `local_adapters.py` (read-only, incremental, "
              "dedupe by a stable id). API: a `fetch_*` function in `accounts.py` and its "
              "host in `ALLOWED_HOSTS`.",
              "3. Synthetic fixtures + tests (no real user data), then regenerate this file.",
              ""]
    return "\n".join(lines)


def main(argv) -> int:
    text = render()
    if "--check" in argv:
        ok = OUT.is_file() and OUT.read_text("utf-8") == text
        print("docs/providers.md is %s" % ("up to date" if ok else "STALE: regenerate"))
        return 0 if ok else 1
    OUT.write_text(text, "utf-8")
    print("wrote", OUT)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
